import * as model from './model.js';
import * as store from './db.js';
import * as providers from './providers.js';
import * as identity from './identity.js';
import {createIdentityUI} from './identity-ui.js';
import {createConsistencyUI} from './scene-consistency-ui.js';
import {createMediaUI} from './media-ui.js';
import {createStoryUI} from './story-ui.js';
import {t, setLanguage, getLanguage, arabicIssues} from './i18n.js';

const $ = (s, root = document) => root.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const testMode = new URLSearchParams(location.search).get('test') === '1';
const state = {db:null, projects:[], currentId:null, view:'home', tab:'overview', selectedEpisode:null, showArchived:false, assets:[], wizard:null, wizardStep:0, wizardDraft:null, theme:'dark',offlineReady:false};
let editorContext = null;
let toastTimer;
let draftTimer;
let pendingDraft = null;
let objectURLs = [];
let installPrompt;
const iconPaths = {
 spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z',
 home:'m3 10 9-7 9 7v10H3V10Zm6 10v-7h6v7',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-6-6 6 6-6 6',
 film:'M4 3h16v18H4V3Zm0 5h16M4 16h16M8 3v18M16 3v18',book:'M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3V4Zm9 2v16',
 users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm8-7a4 4 0 0 1 0 8',
 pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM12 7a3 3 0 1 0 0 6 3 3 0 0 0 0-6Z',
 check:'m5 12 4 4L19 6',shield:'m12 3 9 4v5c0 5-9 10-9 10S3 17 3 12V7l9-4Z',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5',
 folder:'M3 6h7l2 3h9v12H3V6Z',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5',edit:'m15 4 5 5M4 20l5-1L21 7l-5-5L4 14v6Z',
 more:'M5 12h.01M12 12h.01M19 12h.01',close:'m6 6 12 12M6 18 18 6',archive:'M3 3h18v5H3V3Zm2 5v13h14V8M9 12h6',copy:'M9 9h12v12H9V9ZM15 9V3H3v12h6',up:'m6 15 6-6 6 6',down:'m6 9 6 6 6-6',image:'M3 3h18v18H3V3Zm0 14 6-6 4 4 3-3 5 5M15 7h.01',alert:'m12 3 10 18H2L12 3Zm0 6v5m0 3v.01',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 4v5l4 2',play:'m8 4 13 8-13 8V4Z',globe:'M3 12h18M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 0c-5 5-5 13 0 18 5-5 5-13 0-18Z'
};
function icon(name) { return `<svg class="icon" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name] || iconPaths.film}"/></svg>`; }
function button(label,action,cls='secondary',extra='',ico='') {return `<button type="button" class="button ${cls}" data-action="${action}" ${extra}>${ico?icon(ico):''}<span>${esc(label)}</span></button>`;}
function iconButton(label,action,ico,extra='') {return `<button type="button" class="icon-button" aria-label="${esc(label)}" title="${esc(label)}" data-action="${action}" ${extra}>${icon(ico)}</button>`;}
function tag(text,cls='') {return `<span class="badge ${cls}">${esc(text)}</span>`;}
function textBlock(label,value) {return `<div class="detail-block"><h3>${esc(t(label))}</h3><p class="preserve">${esc(value || t('none'))}</p></div>`;}
function project() {return state.projects.find(p=>p.id===state.currentId);}
function activeEpisodes(p=project()) {return (p?.episodes || []).filter(e=>!e.archived).sort((a,b)=>a.number-b.number);}
function selectedEpisode() {const eps=activeEpisodes(); return eps.find(e=>e.id===state.selectedEpisode) || eps[0];}
function title(p) {return p.bible?.title || p.title || t('untitled');}
function localeDate(date) {try {return new Intl.DateTimeFormat(getLanguage()==='ar'?'ar-EG':'en-GB',{day:'numeric',month:'short',year:'numeric'}).format(new Date(date));} catch{return '';}}
function installHelp(){return getLanguage()==='ar'?'على Android Chrome: من قائمة المتصفح اختر تثبيت التطبيق أو إضافة إلى الشاشة الرئيسية بعد فتحه أول مرة عبر HTTPS. القصص تبقى على هذا الجهاز؛ احتفظ بنسخة احتياطية.':'On Android Chrome, use the browser menu → Install app or Add to Home screen after the first HTTPS visit. Stories stay on this device; keep a backup.';}
function installMarkup(compact){return compact?iconButton(t('install'),'install','plus'):button(t('install'),'install','secondary','','plus');}
function installSlot(compact=false){return `<span data-pwa-install="${compact?'compact':'full'}" ${compact?'class="desktop-only"':''} ${installPrompt?'':'hidden'}>${installPrompt?installMarkup(compact):''}</span>`;}
function syncInstallControls(){document.querySelectorAll('[data-pwa-install]').forEach(el=>{el.hidden=!installPrompt;el.innerHTML=installPrompt?installMarkup(el.dataset.pwaInstall==='compact'):'';});}
function toast(message) {const el=$('#toast');el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,4500);}
function optionLabel(value) {const keys={'Mystery':'mystery','Horror':'horror','Adventure':'adventure','Comedy':'comedy','Fantasy':'fantasy','Science Fiction':'sciencefiction','Drama':'drama','Children':'children','Family':'family','Teens':'teens','Adults':'adults','All ages':'allages','Egyptian':'egyptian','Modern Standard Arabic':'msa','Cinematic realistic':'cinematic','3D animation':'animation3d','2D animation':'animation2d','Anime':'anime','Storybook':'storybook','Create for me':'createforme','Direct with me':'directwithme','Idea':'ideaStatus','Planned':'planned','Storyboarded':'storyboarded','Ready for generation':'ready','Generated':'generated','Approved':'approved','Not requested':'notRequested','NOT_CONFIGURED':'notConfigured','Reference only':'referenceOnly'};return t(keys[value]||value);}
function shell(content) {
return `<aside class="sidebar"><a class="brand" href="#" data-action="home"><img src="./icons.svg" width="38" height="38" alt=""><span>CineSaga <strong>AI</strong><small>THE SERIES STUDIO</small></span></a><p class="sidebar-label">${esc(t('director'))}</p><nav class="sidebar-nav" aria-label="${esc(t('home'))}"><button class="nav-item ${state.view==='home'?'active':''}" data-action="home">${icon('home')}${esc(t('home'))}</button><button class="nav-item ${state.view==='workspace'?'active':''}" data-action="projects">${icon('folder')}${esc(t('projects'))}<span class="nav-count">${state.projects.length}</span></button><button class="nav-item" data-action="new">${icon('plus')}${esc(t('newSeries'))}</button></nav><div class="sidebar-bottom"><div class="local-seal">${icon('shield')}<div><strong>${esc(t('localOnly'))}</strong><small>${esc(t('localOnlyNote'))}</small></div></div><button class="nav-item" data-action="data">${icon('download')}${esc(t('settings'))}</button><small class="version">${esc(t('version'))}</small></div></aside><div class="app-content"><header class="topbar"><a href="#" class="mobile-brand" data-action="home"><img src="./icons.svg" width="32" height="32" alt="">CineSaga AI</a><div class="breadcrumb"><span>${esc(t('home'))}</span>${state.view==='workspace'?`<span>/</span><strong>${esc(title(project()))}</strong>`:''}</div><div class="topbar-actions"><span class="save-status">${icon('check')}<span>${esc(t('saved'))}</span></span>${button(t('language'),'language','ghost','','globe')}${iconButton(t('theme'),'theme','sun')}${iconButton(t('settings'),'data','download')}${installSlot(true)}</div></header><main id="main" class="main" tabindex="-1">${content}</main><footer class="page-footer"><span>CineSaga AI</span><span>${esc(t('localOnlyNote'))}</span><span class="offline-status">● ${esc(t(state.offlineReady?'offline':'offlinePending'))}</span></footer></div>`;
}
function heroArt() {return `<div class="hero-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><span class="star star-one">✦</span><span class="star star-two">✧</span><div class="film-frame frame-back"><div class="film-perf"></div><div class="frame-landscape"></div><div class="film-perf"></div></div><div class="film-frame frame-front"><div class="film-perf"></div><div class="frame-scene"><div class="scene-moon"></div><div class="scene-mountain"></div><div class="scene-city"></div><span>01 / THE BEGINNING</span></div><div class="film-perf"></div></div><div class="art-caption">${icon('film')}<span>YOUR NEXT GREAT STORY</span><i></i></div></div>`;}
function homeView() {
const eps=state.projects.reduce((n,p)=>n+activeEpisodes(p).length,0), sc=state.projects.reduce((n,p)=>n+p.episodes.reduce((a,e)=>a+(e.scenes||[]).filter(s=>!s.archived).length,0),0);
return `<section class="hero"><div class="hero-content"><div class="eyebrow"><span class="eyebrow-dot"></span>${esc(t('eyebrow'))}</div><h1 class="hero-title">${esc(t('heroTitle')).replace('\n','<br>')}</h1><p class="hero-copy">${esc(t('heroCopy'))}</p><div class="hero-actions">${button(t('startStory'),'new','primary','','plus')}${button(t('exploreDemo'),'demo','ghost','','play')}</div><div class="hero-footnote">${icon('spark')}<span>${esc(t('local'))}</span></div></div>${heroArt()}</section><div class="stats-row"><div class="stat">${icon('folder')}<strong>${state.projects.length.toString().padStart(2,'0')}</strong><span>${esc(t('series'))}</span></div><div class="stat">${icon('film')}<strong>${String(eps).padStart(2,'0')}</strong><span>${esc(t('episodes'))}</span></div><div class="stat">${icon('image')}<strong>${String(sc).padStart(2,'0')}</strong><span>${esc(t('scenes'))}</span></div><div class="stat local-stat">${icon('shield')}<span>${esc(t('localOnly'))}</span></div></div>${state.wizardDraft?`<div class="callout draft-banner"><div>${tag(t('draft'))} <strong>${esc(t('draftAvailable'))}</strong></div>${button(t('resumeDraft'),'resume-wizard','secondary')}</div>`:''}<section id="projects"><div class="section-heading"><div><h2>${esc(t('yourProjects'))}<span class="count-pill">${state.projects.length}</span></h2><p>${esc(t('projectSub'))}</p></div><div class="toolbar">${state.lastProject&&state.projects.some(p=>p.id===state.lastProject)?button(t('continue'),'continue','ghost','','clock'):''}${button(t('newSeries'),'new','secondary','','plus')}</div></div><div class="project-grid">${state.projects.map(projectCard).join('')}<button class="project-card create-card" data-action="new"><span class="create-orb">${icon('plus')}</span><strong>${esc(t('newSeries'))}</strong><span>${esc(t('createFirst'))}</span></button></div></section>`;
}
function projectCard(p) {return `<article class="project-card"><div class="project-art ${p.demo?'demo-art':'original-art'}"><div class="card-top">${tag(p.demo?t('demo'):optionLabel(p.config.genre),p.demo?'gold':'')}<span class="project-mark">${icon('film')}</span></div><div class="skyline" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div><div class="art-title">${p.demo?'THE CITY<br>BENEATH THE SCHOOL':'A NEW WORLD<br>IN THE MAKING'}</div></div><div class="card-body"><div class="card-meta"><span>${esc(optionLabel(p.config.genre))}</span><span>·</span><span>${activeEpisodes(p).length} ${esc(t('episodes'))}</span>${tag(p.config.language==='ar'?'العربية':'EN')}</div><h3>${esc(title(p))}</h3><p class="project-premise">${esc(p.bible.premise||p.idea)}</p><div class="card-actions"><small>${esc(localeDate(p.updatedAt))}</small>${button(t('open'),'open','ghost',`data-id="${p.id}"`,'arrow')}</div></div></article>`;}
const tabs=[['overview','home'],['story','spark'],['bible','book'],['characters','users'],['identity','shield'],['locations','pin'],['episodes','film'],['storyboard','image'],['continuity','shield'],['assets','folder'],['export','download']];
function workspaceView() {const p=project();if(!p)return homeView();const content={overview:overviewView,story:()=>storyUI.view(),bible:bibleView,characters:()=>entityView('character'),identity:()=>identityUI.view(),locations:()=>entityView('location'),episodes:episodesView,storyboard:storyboardView,continuity:continuityView,assets:assetsView,export:dataView}[state.tab];return `<div class="workspace-heading"><div><div class="eyebrow">${esc(t('planning'))}${p.demo?' · '+esc(t('demo')):''}${p.storyHistory?.length?' · DEMO / NOT REAL AI':''}</div><h1>${esc(title(p))}</h1><p>${esc(optionLabel(p.config.genre))} <span> / </span> ${esc(optionLabel(p.config.visualStyle))} <span> / </span> ${activeEpisodes().length} ${esc(t('episodes'))}</p></div>${button(t('bible'),'tab','secondary','data-tab="bible"','book')}</div><div class="tab-list" role="tablist" aria-label="${esc(t('open'))}">${tabs.map(([key,ico])=>`<button id="tab-${key}" class="tab-button" role="tab" aria-selected="${state.tab===key}" aria-controls="workspace-panel" tabindex="${state.tab===key?0:-1}" data-action="tab" data-tab="${key}">${icon(ico)}${esc(t(key))}${key==='continuity'&&model.checkContinuity(p).some(i=>!i.ignoredReason)?'<i class="issue-dot"></i>':''}</button>`).join('')}</div><div id="workspace-panel" class="workspace-body" role="tabpanel" aria-labelledby="tab-${state.tab}">${content()}</div>`;}
function overviewView(){const p=project(),issues=model.checkContinuity(p).filter(i=>!i.ignoredReason),seconds=p.episodes.reduce((n,e)=>n+e.scenes.filter(s=>!s.archived).reduce((a,s)=>a+Number(s.seconds||0),0),0);return `<div class="split-grid"><section class="panel overview-premise"><div class="section-heading"><h2>${esc(t('premise'))}</h2>${iconButton(t('edit'),'edit-bible','edit')}</div><p class="lead preserve">${esc(p.bible.premise||p.idea)}</p><div class="toolbar">${tag(optionLabel(p.config.audience))}${tag(p.config.language==='ar'?`العربية · ${optionLabel(p.config.dialect)}`:'English')}${tag(optionLabel(p.config.controlMode))}</div><div class="divider"></div>${textBlock('conflict',p.bible.conflict)}${textBlock('ending',p.bible.ending)}</section><section class="panel"><div class="eyebrow">${esc(t('storyHealth'))}</div><div class="health-number">${issues.length.toString().padStart(2,'0')}</div><h2>${esc(issues.length?t('issues'):t('allClear'))}</h2><p class="text-muted">${esc(t('checkerNote'))}</p>${button(t('reviewIssues'),'tab','secondary','data-tab="continuity"','shield')}<div class="divider"></div><div class="summary-line"><span>${esc(t('cast'))}</span><strong>${p.characters.filter(c=>!c.archived).length}</strong></div><div class="summary-line"><span>${esc(t('locations'))}</span><strong>${p.locations.filter(c=>!c.archived).length}</strong></div><div class="summary-line"><span>${esc(t('storyboard'))}</span><strong>${Math.round(seconds/60)} ${esc(t('minutes'))}</strong></div></section></div><section class="panel"><div class="section-heading"><h2>${esc(t('season'))}</h2>${button(t('episodes'),'tab','ghost','data-tab="episodes"','arrow')}</div><div class="season-strip">${activeEpisodes().map(e=>`<button class="season-tile" data-action="episode-board" data-id="${e.id}"><small>${esc(t('episodes'))} ${String(e.number).padStart(2,'0')}</small><strong>${esc(e.title)}</strong>${tag(optionLabel(e.status))}</button>`).join('')}</div></section><div class="provider-note">${icon('spark')}<div><strong>${esc(t('local'))}</strong><p>${esc(t('createNote'))}</p></div></div>`;}
const bibleFields=['title','premise','genreTone','ending','worldRules','timeline','conflict','revealedSecrets','unrevealedSecrets','importantObjects','continuityNotes'];
function bibleView(){const p=project();return `<div class="section-heading"><div><h2>${esc(t('bible'))}</h2><p>${esc(t('localOnly'))}</p></div>${button(t('edit'),'edit-bible','primary','','edit')}</div><div class="split-grid">${bibleFields.map(k=>`<section class="panel">${textBlock(k,p.bible[k])}</section>`).join('')}</div>`;}
function entityView(type){const p=project(),arr=type==='character'?p.characters:p.locations;return `<div class="section-heading"><h2>${esc(t(type==='character'?'characters':'locations'))} <span class="count-pill">${arr.filter(x=>!x.archived).length}</span></h2><div class="toolbar"><label class="checkbox-option"><input type="checkbox" data-setting="archived" ${state.showArchived?'checked':''}>${esc(t('showArchived'))}</label>${button(t(type==='character'?'newCharacter':'newLocation'),'new-entity','primary',`data-type="${type}"`,'plus')}</div></div><div class="entity-grid">${arr.filter(x=>state.showArchived?x.archived:!x.archived).map(x=>entityCard(x,type)).join('')||empty(t(type==='character'?'noCharacters':'noLocations'))}</div>`;}
function entityCard(x,type){return `<article class="entity-card ${x.archived?'archived':''}"><div class="entity-card-header">${x.referenceImageId?`<img class="entity-cover" data-asset="${esc(x.referenceImageId)}" alt="${esc(x.name)}">`:`<div class="reference-placeholder"><span class="avatar">${type==='character'?esc(x.name?.slice(0,1)||'?'):icon('pin')}</span><small>${esc(t('noImage'))}</small></div>`}${x.archived?tag(t('archived')):''}</div><div class="card-body"><div class="card-meta">${esc(type==='character'?x.role:x.timeOfDay)}</div><h3>${esc(x.name)}</h3><p class="preserve">${esc(type==='character'?x.personality:x.description)}</p><div class="entity-details">${type==='character'?`<span>${esc(x.ageRange)}</span><span>${esc(t('firstEpisode'))} ${x.firstEpisode}</span>`:`<span>${esc(x.atmosphere)}</span>`}</div><div class="entity-actions">${button(t('edit'),'edit-entity','ghost',`data-type="${type}" data-id="${x.id}"`,'edit')}${iconButton(t('duplicate'),'duplicate-entity','copy',`data-type="${type}" data-id="${x.id}"`)}${iconButton(t(x.archived?'restore':'archive'),x.archived?'restore-entity':'archive-entity','archive',`data-type="${type}" data-id="${x.id}"`)}</div></div></article>`;}
function empty(message){return `<div class="empty-state">${icon('film')}<h3>${esc(message)}</h3></div>`;}
function episodeContinuity(e){const prev=activeEpisodes().filter(x=>x.number<e.number).at(-1);if(!prev)return '';return `<div class="continuity-panel"><div class="eyebrow">${esc(t('previousEnding'))} · ${prev.number}</div><p class="preserve">${esc(prev.ending||t('noPreviousEnding'))}</p><div class="continuity-grid">${['continuedFrom','continuityFacts','unresolvedEvents','currentStates'].map(k=>textBlock(k,e[k])).join('')}</div></div>`;}
function episodesView(){return `<div class="section-heading"><h2>${esc(t('episodes'))}</h2><div class="toolbar"><label class="checkbox-option"><input type="checkbox" data-setting="archived" ${state.showArchived?'checked':''}>${esc(t('showArchived'))}</label>${button(t('newEpisode'),'new-episode','primary','','plus')}</div></div><div class="episode-list">${project().episodes.filter(e=>state.showArchived?e.archived:!e.archived).sort((a,b)=>a.number-b.number).map(e=>`<article class="episode-card ${e.archived?'archived':''}"><div class="episode-number">${String(e.number).padStart(2,'0')}</div><div class="episode-main"><div class="section-heading"><h3>${esc(e.title)}</h3>${tag(optionLabel(e.status))}</div><p class="preserve">${esc(e.mainEvent)}</p><div class="episode-meta"><span>${icon('clock')}${e.durationMinutes} ${esc(t('minutes'))}</span><span>${e.scenes.filter(s=>!s.archived).length} ${esc(t('scenes'))}</span></div><details><summary>${esc(t('overview'))}</summary><div class="split-grid">${['beginning','mainEvent','turningPoint','episodeEnding'].map(k=>textBlock(k,e[k==='episodeEnding'?'ending':k])).join('')}${textBlock('characters',e.characterIds.map(id=>project().characters.find(c=>c.id===id)?.name||id).join(', '))}${textBlock('locations',e.locationIds.map(id=>project().locations.find(c=>c.id===id)?.name||id).join(', '))}</div></details>${episodeContinuity(e)}<div class="entity-actions">${button(t('openStoryboard'),'episode-board','secondary',`data-id="${e.id}"`,'image')}${button(t('edit'),'edit-episode','ghost',`data-id="${e.id}"`,'edit')}${iconButton(t(e.archived?'restore':'archive'),e.archived?'restore-episode':'archive-episode','archive',`data-id="${e.id}"`)}</div></div></article>`).join('')||empty(t('noEpisodes'))}</div>`;}
function storyboardView(){const e=selectedEpisode();return `<div class="section-heading"><div><h2>${esc(t('storyboard'))}</h2>${e?`<p>${e.scenes.filter(s=>!s.archived).reduce((n,s)=>n+Number(s.seconds),0)} / ${e.durationMinutes*60} s</p>`:''}</div><div class="toolbar">${e?`<label class="sr-only" for="episode-select">${esc(t('selectEpisode'))}</label><select id="episode-select">${activeEpisodes().map(ep=>`<option value="${ep.id}" ${ep.id===e.id?'selected':''}>${ep.number}. ${esc(ep.title)}</option>`).join('')}</select><label class="checkbox-option"><input type="checkbox" data-setting="archived" ${state.showArchived?'checked':''}>${esc(t('showArchived'))}</label>${button(t('newScene'),'new-scene','primary','','plus')}`:''}</div></div>${e?`<div class="scene-list">${e.scenes.filter(s=>state.showArchived?s.archived:!s.archived).map((s)=>sceneCard(s,e)).join('')||empty(t('noScenes'))}</div>`:empty(t('noEpisodes'))}`;}
function sceneCard(s,e){return `<article class="scene-card ${s.archived?'archived':''}"><div class="scene-header"><div><span class="scene-index">${String(s.number).padStart(2,'0')}</span><strong>${esc(project().locations.find(l=>l.id===s.locationId)?.name||t('noLocation'))}</strong></div><span class="badge">${s.seconds} s</span></div><div class="scene-body"><div class="scene-visual">${icon('image')}<p>${esc(s.visual)}</p><span>${esc(s.camera)}</span></div><div class="scene-content"><div class="scene-meta">${s.characterIds.map(id=>tag(project().characters.find(c=>c.id===id)?.name||id)).join('')}</div>${textBlock('action',s.action)}${s.dialogue?textBlock('dialogue',s.dialogue):''}<details><summary>${esc(t('overview'))}</summary>${['narration','sound','music','knowledgeUsed','appearanceOverrides','clothingOverrides'].map(k=>textBlock(k,s[k])).join('')}${textBlock('sceneTimeline',s.timeline)}</details><div class="generation-status"><span>${esc(t('imageStatus'))}: ${esc(optionLabel(s.imageStatus))}</span><span>${esc(t('videoStatus'))}: ${esc(optionLabel(s.videoStatus))}</span></div></div></div>${consistencyUI.view(project(),s)}${mediaUI.view(project(),s)}<div class="scene-actions">${button(t('edit'),'edit-scene','ghost',`data-id="${s.id}"`,'edit')}${iconButton(t('moveUp'),'move-scene','up',`data-id="${s.id}" data-delta="-1" ${e.scenes.indexOf(s)===0?'disabled':''}`)}${iconButton(t('moveDown'),'move-scene','down',`data-id="${s.id}" data-delta="1" ${e.scenes.indexOf(s)===e.scenes.length-1?'disabled':''}`)}${iconButton(t('duplicate'),'duplicate-scene','copy',`data-id="${s.id}"`)}${iconButton(t(s.archived?'restore':'archive'),s.archived?'restore-scene':'archive-scene','archive',`data-id="${s.id}"`)}</div></article>`;}
function continuityView(){const p=project(),issues=model.checkContinuity(p),active=issues.filter(i=>!i.ignoredReason);return `<div class="section-heading"><div><h2>${esc(t('continuity'))} <span class="count-pill">${active.length}</span></h2><p>${esc(t('checkerNote'))}</p></div>${button(t('checkAgain'),'check','secondary','','shield')}</div><div class="issue-list">${active.map(issueCard).join('')||`<div class="callout success">${icon('check')}${esc(t('allClear'))}</div>`}</div>${issues.some(i=>i.ignoredReason)?`<details class="panel"><summary>${esc(t('ignored'))} (${issues.length-active.length})</summary>${issues.filter(i=>i.ignoredReason).map(issueCard).join('')}</details>`:''}<section class="panel"><div class="section-heading"><h2>${esc(t('storyEvents'))}</h2>${button(t('trackEvent'),'new-event','secondary','','plus')}</div>${p.events.map(ev=>`<div class="event-row"><div><strong>${esc(ev.description)}</strong><p>${esc(t('introducedEpisode'))}: ${ev.introducedEpisode} · ${esc(t('resolvedEpisode'))}: ${ev.resolvedEpisode||0}</p></div>${iconButton(t('edit'),'edit-event','edit',`data-id="${ev.id}"`)}</div>`).join('')||`<p class="text-muted">${esc(t('noEvents'))}</p>`}</section>`;}
function issueCard(i){const e=project().episodes.find(e=>e.id===i.episodeId),s=e?.scenes.find(s=>s.id===i.sceneId),localized=getLanguage()==='ar'?arabicIssues[i.rule]:null;return `<article class="issue-card ${i.ignoredReason?'ignored':''}"><div class="issue-icon">${icon('alert')}</div><div class="issue-content"><div class="card-meta">${esc(e?`${t('episodes')} ${e.number}`:t('series'))}${s?` / ${esc(t('scene'))} ${s.number}`:''} · ${esc(i.rule)}</div><h3>${esc(localized?.[0]||i.message)}</h3><p class="issue-evidence"><strong>${esc(t('evidence'))}:</strong> ${esc(i.evidence)}</p><p><strong>${esc(t('suggestion'))}:</strong> ${esc(localized?.[1]||i.suggestion)}</p>${i.ignoredReason?`<p><strong>${esc(t('ignoreReason'))}:</strong> ${esc(i.ignoredReason)}</p>`:''}<div class="entity-actions">${button(t(i.ignoredReason?'reopen':'ignore'),i.ignoredReason?'reopen-issue':'ignore-issue','ghost',`data-id="${esc(i.id)}"`)}${e?button(t('edit'),s?'edit-issue-scene':'edit-episode','ghost',`data-id="${s?s.id:e.id}" data-episode="${e.id}"`,'edit'):''}</div></div></article>`;}
function assetsView(){const p=project(),refs=[...p.characters.map(c=>({...c,kind:'character'})),...p.locations.map(l=>({...l,kind:'location'}))].filter(x=>x.referenceImageId);return `<div class="section-heading"><div><h2>${esc(t('assets'))}</h2><p>${esc(t('assetsHint'))}</p></div></div><div class="asset-grid">${refs.map(x=>`<article class="asset-card"><img data-asset="${esc(x.referenceImageId)}" alt="${esc(x.name)}"><div class="card-body"><h3>${esc(x.name)}</h3>${tag(t('referenceOnly'))}${button(t('edit'),'edit-entity','ghost',`data-id="${x.id}" data-type="${x.kind}"`,'edit')}</div></article>`).join('')||empty(t('noAssets'))}</div><section class="panel"><h2>${esc(t('futureTools'))}</h2><p>${esc(t('providerExplain'))}</p><div class="provider-grid">${['TextStoryProvider','ImageGenerationProvider','VideoGenerationProvider','VoiceGenerationProvider','MusicGenerationProvider'].map(k=>`<div class="provider-card"><strong>${esc(k.replace('GenerationProvider','').replace('StoryProvider',' story'))}</strong>${tag('NOT_CONFIGURED')}${button(t('tryProvider'),'provider','ghost',`data-provider="${k}"`)}</div>`).join('')}</div></section>`;}
function dataView(){return `<section class="panel export-panel"><div class="export-orb">${icon('download')}</div><h1>${esc(t('exportTitle'))}</h1><p>${esc(t('exportHint'))}</p>${globalThis.CineSagaAndroid?'':`<p>${esc(installHelp())}</p>${installSlot()}`}<div class="toolbar">${button(t('exportAll'),'export-all','primary','','download')}${button(t('import'),'import','secondary','','upload')}</div><input type="file" id="import-file" accept="application/json,.json" hidden></section><section class="panel danger-zone"><h2>${esc(t('deleteAll'))}</h2><p>${esc(t('deleteHint'))}</p><p class="text-muted">${esc(t('backupBefore'))}</p>${button(t('deleteAll'),'delete-all','danger','','archive')}</section>`;}

function render(){mediaUI.dispose();objectURLs.forEach(URL.revokeObjectURL);objectURLs=[];document.title=`${state.view==='workspace'&&project()?title(project())+' · ':''}CineSaga AI`;document.documentElement.dataset.theme=state.theme;$('.skip-link').textContent=t('skip');$('#app').innerHTML=shell(state.view==='wizard'?wizardView():state.view==='workspace'?workspaceView():state.view==='data'?dataView():homeView());identityUI.decorate();loadImages();}
async function loadImages(){identityUI.decorate();document.querySelectorAll('.preserve,.project-premise,.scene-visual p,.workspace-heading h1,.entity-card h3,.episode-main h3,.season-tile strong,.scene-header strong,.asset-card h3,.card-body h3,.issue-evidence,textarea,input[type="text"]').forEach(el=>el.dir='auto');const images=[...document.querySelectorAll('[data-asset]')];for(const img of images){try{const asset=await store.getAsset(img.dataset.asset,state.db);if(asset?.blob&&img.isConnected){const url=URL.createObjectURL(asset.blob);objectURLs.push(url);img.src=url;}}catch{img.alt=t('noImage');}}}
async function persist(p=project()){const candidate=structuredClone(p);candidate.updatedAt=new Date().toISOString();if(candidate.bible?.title)candidate.title=candidate.bible.title;await store.saveProject(candidate,state.db);state.projects[state.projects.findIndex(x=>x.id===candidate.id)]=candidate;return candidate;}
async function mutateProject(change){const candidate=structuredClone(project());change(candidate);await persist(candidate);}
async function openProject(id){state.currentId=id;state.view='workspace';state.tab='overview';state.showArchived=false;state.selectedEpisode=null;state.lastProject=id;await store.setSetting('lastProject',id,state.db);render();window.scrollTo(0,0);}

const wizardSteps=[
 {key:'idea',prompt:'ideaPrompt',type:'textarea'},
 {key:'genre',prompt:'genrePrompt',choices:['Mystery','Horror','Adventure','Comedy','Fantasy','Science Fiction','Drama','Children']},
 {key:'audience',prompt:'audiencePrompt',choices:['Children','Family','Teens','Adults','All ages']},
 {key:'language',prompt:'languagePrompt',choices:['en','ar']},
 {key:'dialect',prompt:'dialectPrompt',choices:['Egyptian','Modern Standard Arabic']},
 {key:'visualStyle',prompt:'visualPrompt',choices:['Cinematic realistic','3D animation','2D animation','Anime','Storybook']},
 {key:'episodeCount',prompt:'countPrompt',type:'number',min:1,max:24},
 {key:'episodeMinutes',prompt:'durationPrompt',type:'number',min:1,max:120,label:'durationMinutes'},
 {key:'controlMode',prompt:'controlPrompt',choices:['Create for me','Direct with me']}
];
function currentSteps(){return wizardSteps.filter(s=>s.key!=='dialect'||state.wizard.language==='ar');}
function wizardView(){const steps=currentSteps(),step=steps[state.wizardStep],review=!step;return `<section class="wizard"><div class="wizard-header"><div class="eyebrow">${esc(t('newSeries'))}</div><h1>${esc(t('wizardTitle'))}</h1><p>${esc(t('wizardSubtitle'))}</p></div><div class="wizard-progress" aria-label="${esc(t('step'))} ${state.wizardStep+1} ${esc(t('of'))} ${steps.length+1}">${[...steps,{}].map((_,i)=>`<span class="${i<=state.wizardStep?'complete':''}"></span>`).join('')}</div><form id="wizard-form"><div class="wizard-step"><div class="wizard-count">${esc(t('step'))} ${String(state.wizardStep+1).padStart(2,'0')} / ${steps.length+1}</div><h2>${esc(t(review?'review':step.prompt))}</h2><p>${esc(t(review?'createNote':step.label||step.key))}</p>${review?`<div class="review-grid">${steps.map(s=>`<div class="review-item ${s.key==='idea'?'full':''}"><small>${esc(t(s.label||s.key))}</small><strong class="preserve">${esc(s.choices?optionLabel(state.wizard[s.key]):state.wizard[s.key])}</strong></div>`).join('')}</div><div class="provider-note">${icon('spark')}<span>${esc(t('local'))}</span></div>`:step.choices?`<div class="choice-grid">${step.choices.map((value,i)=>`<label class="choice-card ${state.wizard[step.key]===value?'selected':''}"><input type="radio" name="${step.key}" value="${esc(value)}" ${state.wizard[step.key]===value?'checked':''} required><span>${esc(optionLabel(value))}</span>${state.wizard[step.key]===value?icon('check'):''}</label>`).join('')}</div>`:step.type==='textarea'?`<label class="sr-only" for="wizard-input">${esc(t(step.key))}</label><textarea id="wizard-input" name="idea" required minlength="8" maxlength="5000" placeholder="${esc(t('ideaPlaceholder'))}">${esc(state.wizard.idea)}</textarea>`:`<label for="wizard-input">${esc(t(step.label||step.key))}</label><input id="wizard-input" name="${step.key}" type="number" required min="${step.min}" max="${step.max}" step="1" value="${esc(state.wizard[step.key])}">`}</div><div class="wizard-actions">${button(t(state.wizardStep?'back':'cancel'),state.wizardStep?'wizard-back':'home','ghost')}<span class="draft-status">${esc(t('draftSaved'))}</span><button type="submit" class="button primary">${esc(t(review?'create':'next'))}${icon(review?'spark':'arrow')}</button></div></form></section>`;}
async function beginWizard(resume=false){state.wizard=resume&&state.wizardDraft?structuredClone(state.wizardDraft.config):{idea:'',genre:'Mystery',audience:'Family',language:getLanguage(),dialect:'Egyptian',visualStyle:'Cinematic realistic',episodeCount:6,episodeMinutes:5,controlMode:'Direct with me'};state.wizardStep=resume?Math.min(state.wizardDraft.step,currentSteps().length):0;state.view='wizard';render();$('#wizard-input')?.focus();}
function captureWizard(){const form=$('#wizard-form');if(!form)return;const steps=currentSteps(),step=steps[state.wizardStep];if(!step)return;const data=new FormData(form);if(data.has(step.key))state.wizard[step.key]=step.type==='number'?Number(data.get(step.key)):data.get(step.key);}
async function saveWizardDraft(){state.wizardDraft={config:structuredClone(state.wizard),step:state.wizardStep};await store.saveDraft('wizard',state.wizardDraft,state.db);}
async function wizardSubmit(event){event.preventDefault();captureWizard();const steps=currentSteps();if(state.wizardStep<steps.length){state.wizardStep++;await saveWizardDraft();render();$('#wizard-input')?.focus();return;}const submit=event.submitter;submit.disabled=true;try{const p=model.createSeries(state.wizard);await store.saveProject(p,state.db);state.projects.unshift(p);await store.deleteDraft('wizard',state.db);state.wizardDraft=null;await openProject(p.id);if(p.config.controlMode==='Create for me'){state.tab='story';await storyUI.load();render();}toast(t('projectCreated'));}catch(error){submit.disabled=false;toast(error.message);}}

const characterFields=['name','role','ageRange','appearance','clothing','personality','voice','goals','fears','relationships','knows','doesNotKnow','firstEpisode'];
const locationFields=['name','description','timeOfDay','lighting','atmosphere','importantObjects','purpose'];
const episodeFields=['number','title','beginning','mainEvent','turningPoint','ending','characterIds','locationIds','durationMinutes','status','continuedFrom','continuityFacts','unresolvedEvents','currentStates','timelineStart'];
const sceneFields=['locationId','characterIds','visual','camera','action','dialogue','narration','sound','music','seconds','knowledgeUsed','appearanceOverrides','clothingOverrides','timeline'];
function field(key,value,kind=''){let type='textarea',choices=null,label=key;
 if(['name','title','role','ageRange','voice','timeOfDay','lighting','atmosphere','camera'].includes(key))type='text';
 if(['firstEpisode','number','durationMinutes','seconds','timelineStart','timeline','introducedEpisode','resolvedEpisode'].includes(key))type='number';
 if(key==='timeline'&&kind==='bible')type='textarea';
 if(key==='ending'&&kind==='episode')label='episodeEnding';
 if(key==='timeline'&&kind==='scene')label='sceneTimeline';
 if(key==='description'&&kind==='event')label='eventDescription';
 if(key==='status'){type='select';choices=model.EPISODE_STATUSES.map(x=>[x,optionLabel(x)]);}
 if(key==='locationId'){type='select';choices=[['',t('choose')],...project().locations.filter(l=>!l.archived||l.id===value).map(l=>[l.id,l.name+(l.archived?` (${t('archived')})`:'')])];}
 if(key==='characterIds'||key==='locationIds'){const arr=key==='characterIds'?project().characters:project().locations;return `<fieldset class="field full"><legend>${esc(t(key))}</legend><div class="checkbox-list">${arr.filter(x=>!x.archived||(value||[]).includes(x.id)).map(x=>`<label class="checkbox-option"><input type="checkbox" name="${key}" value="${x.id}" ${(value||[]).includes(x.id)?'checked':''}>${esc(x.name)}${x.archived?' · '+esc(t('archived')):''}</label>`).join('')||esc(t('none'))}</div></fieldset>`;}
 const required=['name','title','description'].includes(key)||(kind==='scene'&&['visual','locationId'].includes(key));
 const full=type==='textarea'||key==='title';
 const min=['timeline','timelineStart','resolvedEpisode'].includes(key)?0:1,max=key==='seconds'?7200:key==='durationMinutes'?120:9999;
 return `<div class="field ${full?'full':''}"><label for="field-${key}">${esc(t(label))}${required?' <span aria-hidden="true">*</span>':''}</label>${type==='select'?`<select id="field-${key}" name="${key}" ${required?'required':''}>${choices.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select>`:type==='textarea'?`<textarea id="field-${key}" name="${key}" rows="3" maxlength="12000" ${required?'required':''}>${esc(value)}</textarea>`:`<input id="field-${key}" name="${key}" type="${type}" value="${esc(value)}" ${type==='number'?`min="${min}" max="${max}" step="1"`: 'maxlength="500"'} ${required||type==='number'&&!['timeline','timelineStart'].includes(key)?'required':''}>`}</div>`;
}
function collectForm(form,keys,original){const data=new FormData(form),result=structuredClone(original);for(const key of keys){if(['characterIds','locationIds'].includes(key))result[key]=data.getAll(key);else if(['firstEpisode','number','durationMinutes','seconds','introducedEpisode','resolvedEpisode'].includes(key))result[key]=Number(data.get(key));else if(['timeline','timelineStart'].includes(key)&&form.elements[key]?.type==='number')result[key]=data.get(key)===''?'':Number(data.get(key));else result[key]=String(data.get(key)??'').trim();}return result;}
async function openEditor(kind,id=null,episodeId=null){const p=project();let original,fields,titleKey;
 if(kind==='bible'){original=p.bible;fields=bibleFields;titleKey='bible';}
 if(kind==='character'){original=p.characters.find(x=>x.id===id)||model.newCharacter();fields=characterFields;titleKey=id?'editCharacter':'newCharacter';}
 if(kind==='location'){original=p.locations.find(x=>x.id===id)||model.newLocation();fields=locationFields;titleKey=id?'editLocation':'newLocation';}
 if(kind==='episode'){original=p.episodes.find(x=>x.id===id)||model.newEpisode(Math.max(0,...p.episodes.map(e=>e.number))+1,p.config.episodeMinutes);fields=episodeFields;titleKey=id?'editEpisode':'newEpisode';if(!id){const prev=activeEpisodes().at(-1);original.continuedFrom=prev?.ending||'';}}
 if(kind==='scene'){const e=p.episodes.find(e=>e.id===episodeId)||selectedEpisode();episodeId=e.id;original=e.scenes.find(x=>x.id===id)||model.newScene(e.scenes.length+1);fields=sceneFields;titleKey=id?'editScene':'newScene';if(!id)original.timeline=e.timelineStart;}
 if(kind==='event'){original=p.events.find(x=>x.id===id)||{id:model.uid(),description:'',introducedEpisode:1,resolvedEpisode:0};fields=['description','introducedEpisode','resolvedEpisode'];titleKey=id?'editEvent':'trackEvent';}
 const key=`${p.id}:${kind}:${id||'new'}${episodeId?':'+episodeId:''}`;
 const draft=await store.getDraft(key,state.db);let values=draft?.data||original;
 editorContext={kind,id:original.id,original:structuredClone(original),fields,key,episodeId,referenceImageId:values.referenceImageId};
 const dialog=$('#editor');dialog.innerHTML=`<form id="edit-form"><header class="modal-header"><h2 id="modal-title">${esc(t(titleKey))}</h2>${iconButton(t('close'),'close-modal','close')}</header><div class="modal-body">${draft?`<div class="callout">${esc(t('draftRestored'))}</div>`:''}<div class="form-grid">${fields.map(k=>field(k,values[k],kind)).join('')}${['character','location'].includes(kind)?`<div class="field full"><label for="reference-file">${esc(t('reference'))}</label>${values.referenceImageId?`<img class="reference-image" data-asset="${esc(values.referenceImageId)}" alt="${esc(values.name)}">`:`<div class="upload-zone">${icon('image')}<span>${esc(t('noImage'))}</span></div>`}<input id="reference-file" type="file" accept="image/png,image/jpeg,image/webp,image/gif"><small class="text-muted">${esc(t('referenceHint'))}</small></div>`:''}</div>${kind==='scene'?`<div class="provider-note"><span>${esc(t('providerNote'))}</span></div>`:''}<p class="draft-status" aria-live="polite">${esc(t('draftSaved'))}</p></div><footer class="modal-actions">${button(t('cancel'),'close-modal','ghost')}<button type="submit" class="button primary">${icon('check')}${esc(t('save'))}</button></footer></form>`;dialog.showModal();loadImages();}
async function queueDraft(){if(!editorContext||!$('#edit-form'))return;const context=editorContext;const data=collectForm($('#edit-form'),context.fields,context.original);if(context.referenceImageId)data.referenceImageId=context.referenceImageId;pendingDraft={key:context.key,value:{projectId:state.currentId,data}};clearTimeout(draftTimer);draftTimer=setTimeout(()=>flushDraft().catch(e=>toast(e.message)),300);}
async function flushDraft(){clearTimeout(draftTimer);if(pendingDraft){const d=pendingDraft;pendingDraft=null;await store.saveDraft(d.key,d.value,state.db);}}
async function closeEditor(){await flushDraft();$('#editor').close();editorContext=null;}
async function saveEditor(event){event.preventDefault();if(!editorContext)return;const context=editorContext,form=event.target,p=structuredClone(project()),submit=event.submitter;submit.disabled=true;let committed=false;try{await flushDraft();const values=collectForm(form,context.fields,context.original);if(context.referenceImageId)values.referenceImageId=context.referenceImageId;
 if(context.kind==='episode'&&p.episodes.some(e=>e.id!==values.id&&e.number===values.number))throw new Error(getLanguage()==='ar'?'رقم الحلقة مستخدم بالفعل.':'This episode number is already in use.');
 if(context.kind==='scene'&&p.identitySchemaVersion)Object.assign(values,identity.bindScene(p,p.episodes.find(e=>e.id===context.episodeId),values));
 if(context.kind==='bible'){p.bible=values;}else{const array=context.kind==='character'?p.characters:context.kind==='location'?p.locations:context.kind==='episode'?p.episodes:context.kind==='event'?p.events:p.episodes.find(e=>e.id===context.episodeId).scenes;const idx=array.findIndex(x=>x.id===values.id);if(idx>=0)array[idx]=values;else array.push(values);}
 await persist(p);committed=true;await store.deleteDraft(context.key,state.db);$('#editor').close();editorContext=null;render();toast(t('updated'));}catch(error){if(committed){$('#editor').close();editorContext=null;render();}else submit.disabled=false;toast(committed?`${t('updated')} ${error.message}`:error.message||t('error'));}}
async function uploadReference(file){if(!file||!editorContext)return;if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type)||file.size>8*1024*1024){toast(t('referenceHint'));$('#reference-file').value='';return;}const context=editorContext,id=model.uid(),projectId=state.currentId;await store.saveAsset({id,projectId,blob:file,name:file.name,type:file.type},state.db);if(editorContext!==context||!$('#edit-form'))return;context.referenceImageId=id;await queueDraft();await flushDraft();if(editorContext!==context||!$('#reference-file'))return;const old=$('.reference-image',$('#editor'));const img=old||document.createElement('img');img.className='reference-image';img.alt=file.name;img.dataset.asset=id;$('.upload-zone',$('#editor'))?.remove();if(!old)$('#reference-file').before(img);await loadImages();toast(t('draftSaved'));}

function confirmation(titleKey,body,onConfirm,{danger=false,typed=false,formHTML=''}={}){const dialog=$('#editor');editorContext=null;dialog.innerHTML=`<form id="confirm-form"><header class="modal-header"><h2 id="modal-title">${esc(t(titleKey))}</h2>${iconButton(t('close'),'close-modal','close')}</header><div class="modal-body"><p>${esc(body)}</p>${formHTML}${typed?`<div class="field"><label for="typed-confirm">${esc(t('typeDelete'))}</label><input id="typed-confirm" name="typed" autocomplete="off" required pattern="DELETE CINESAGA AI" dir="ltr"></div>`:''}</div><footer class="modal-actions">${button(t('cancel'),'close-modal','ghost')}<button type="submit" class="button ${danger?'danger':'primary'}">${esc(t(typed?'deleteConfirm':'confirm'))}</button></footer></form>`;dialog.showModal();$('#confirm-form').addEventListener('submit',async event=>{event.preventDefault();const submit=event.submitter;submit.disabled=true;try{await onConfirm(new FormData(event.target));dialog.close();}catch(error){submit.disabled=false;toast(error.message);}});}
function locateEntity(type,id){const p=project();const array=type==='character'?p.characters:type==='location'?p.locations:type==='episode'?p.episodes:selectedEpisode()?.scenes;return {array,index:array?.findIndex(x=>x.id===id)};}
async function changeEntity(type,id,operation){const episodeId=selectedEpisode()?.id;await mutateProject(p=>{const array=type==='character'?p.characters:type==='location'?p.locations:type==='episode'?p.episodes:p.episodes.find(e=>e.id===episodeId).scenes;const index=array.findIndex(x=>x.id===id);if(index<0)throw new Error('Item no longer exists.');if(operation==='duplicate'){const copy=model.duplicateEntity(array[index]);if(type==='scene'){copy.number=array.length+1;copy.characterBindings=[];if(p.identitySchemaVersion)Object.assign(copy,identity.bindScene(p,p.episodes.find(e=>e.id===episodeId),copy));}array.push(copy);}else array[index]=operation==='archive'?model.archiveEntity(array[index]):model.restoreEntity(array[index]);});render();toast(t(operation==='duplicate'?'duplicated':operation==='archive'?'archivedToast':'restored'));}
async function exportAll(){await flushDraft();const backup=await store.exportBackup(state.db),validation=model.validateBackup(backup);if(!validation.valid)throw new Error(validation.errors.join(' '));const url=URL.createObjectURL(new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`cinesaga-ai-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast(t('exported'));}
async function importFile(file){if(!file)return;try{if(file.size>40*1024*1024)throw new Error('Backup must be 40 MB or smaller.');const backup=JSON.parse(await file.text()),validation=model.validateBackup(backup);if(!validation.valid)throw new Error(validation.errors.join(' '));confirmation('importConfirm',`${backup.projects.length} ${t('importCount')}`,async data=>{await store.importBackup(backup,data.get('mode'),state.db);await refresh();state.currentId=null;state.view='home';render();toast(t('importSuccess'));},{formHTML:`<div class="field"><label class="checkbox-option"><input type="radio" name="mode" value="merge" checked> ${esc(t('merge'))}</label><p class="text-muted">${esc(t('mergeHint'))}</p><label class="checkbox-option"><input type="radio" name="mode" value="replace"> ${esc(t('replace'))}</label><p class="text-muted">${esc(t('replaceHint'))}</p></div>`});}catch(error){toast(`${t('invalidFile')} ${error.message}`);}}

async function handleAction(event){const el=event.target.closest('[data-action]');if(!el||el.disabled)return;event.preventDefault();const action=el.dataset.action,id=el.dataset.id;try{
 if(action.startsWith('identity-'))await identityUI.handleAction(el);
 else if(action.startsWith('story-'))await storyUI.handleAction(el);
 else if(action==='consistency-preview')await consistencyUI.handleAction(el);
 else if(action.startsWith('media-'))await mediaUI.handleAction(el);
 else if(action==='home'||action==='projects'){if(state.view==='wizard'){captureWizard();await saveWizardDraft();}state.view='home';render();if(action==='projects')$('#projects')?.scrollIntoView({behavior:'smooth'});}
 else if(action==='new')await beginWizard();
 else if(action==='resume-wizard')await beginWizard(true);
 else if(action==='wizard-back'){captureWizard();state.wizardStep=Math.max(0,state.wizardStep-1);await saveWizardDraft();render();}
 else if(action==='demo'){let p=state.projects.find(p=>p.demo);if(!p){p=model.createDemoSeries(getLanguage());await store.saveProject(p,state.db);state.projects.unshift(p);}await openProject(p.id);}
 else if(action==='continue')await openProject(state.lastProject);
 else if(action==='open')await openProject(id);
 else if(action==='tab'){state.tab=el.dataset.tab;state.showArchived=false;if(state.tab==='story')await storyUI.load();render();$(`#tab-${state.tab}`)?.focus({preventScroll:true});}
 else if(action==='data'){state.view='data';render();}
 else if(action==='theme'){state.theme=state.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=state.theme;await store.setSetting('theme',state.theme,state.db);}
 else if(action==='language'){setLanguage(getLanguage()==='en'?'ar':'en');await store.setSetting('language',getLanguage(),state.db);render();}
 else if(action==='episode-board'){state.selectedEpisode=id;state.tab='storyboard';state.showArchived=false;render();}
 else if(action==='edit-bible')await openEditor('bible');
 else if(action==='new-entity')await openEditor(el.dataset.type);
 else if(action==='edit-entity')await openEditor(el.dataset.type,id);
 else if(action==='new-episode')await openEditor('episode');
 else if(action==='edit-episode')await openEditor('episode',id);
 else if(action==='new-scene')await openEditor('scene');
 else if(action==='edit-scene'||action==='edit-issue-scene')await openEditor('scene',id,el.dataset.episode);
 else if(action==='new-event')await openEditor('event');
 else if(action==='edit-event')await openEditor('event',id);
 else if(action==='close-modal')await closeEditor();
 else if(/^(archive|restore|duplicate)-(entity|episode|scene)$/.test(action)){const [op,kind]=action.split('-'),type=kind==='entity'?el.dataset.type:kind;if(op==='archive')confirmation('confirmArchive',t('archiveNote'),()=>changeEntity(type,id,op));else await changeEntity(type,id,op);}
 else if(action==='move-scene'){const episodeId=selectedEpisode().id;await mutateProject(p=>{const e=p.episodes.find(e=>e.id===episodeId),from=e.scenes.findIndex(s=>s.id===id);e.scenes=model.reorderScenes(e.scenes,from,from+Number(el.dataset.delta));});render();}
 else if(action==='check'){render();toast(t('updated'));}
 else if(action==='ignore-issue'){confirmation('ignore',t('checkerNote'),async data=>{const reason=String(data.get('reason')).trim();if(reason.length<3)throw new Error(t('required'));await mutateProject(p=>{p.ignoredIssues[id]=reason;});render();},{formHTML:`<div class="field"><label for="ignore-reason">${esc(t('ignoreReason'))}</label><textarea id="ignore-reason" name="reason" required minlength="3" maxlength="1000"></textarea></div>`});}
 else if(action==='reopen-issue'){await mutateProject(p=>{delete p.ignoredIssues[id];});render();}
 else if(action==='provider'){const result=await new providers[el.dataset.provider]().generate({project:project(),scene:selectedEpisode()?.scenes.find(s=>!s.archived),requirements:el.dataset.provider==='VideoGenerationProvider'?{clipSeconds:selectedEpisode()?.scenes[0]?.seconds||0}: {}});confirmation('providerNote',result.reasons.join('\n'),async()=>{});}
 else if(action==='export-all')await exportAll();
 else if(action==='import')$('#import-file')?.click();
 else if(action==='delete-all')confirmation('deleteAll',t('deleteHint'),async()=>{await store.clearAll(state.db);await store.setSetting('demoSeeded',true,state.db);state.currentId=null;state.lastProject=null;state.wizardDraft=null;state.projects=[];state.view='home';render();toast(t('deleted'));},{danger:true,typed:true});
 else if(action==='install'&&installPrompt){const pendingInstall=installPrompt;installPrompt=null;syncInstallControls();try{await pendingInstall.prompt();await pendingInstall.userChoice;}catch{toast(installHelp());}}
 }catch(error){toast(error.message||t('error'));}}

document.addEventListener('click',handleAction);
document.addEventListener('submit',event=>{if(event.target.id==='wizard-form')wizardSubmit(event).catch(e=>toast(e.message));if(event.target.id==='edit-form')saveEditor(event).catch(e=>toast(e.message));});
document.addEventListener('input',event=>{if(event.target.closest('#edit-form'))queueDraft().catch(e=>toast(e.message));if(event.target.closest('#wizard-form')){captureWizard();saveWizardDraft().catch(e=>toast(e.message));}});
document.addEventListener('change',async event=>{try{if(event.target.dataset.setting==='archived'){state.showArchived=event.target.checked;render();}else if(event.target.id==='episode-select'){state.selectedEpisode=event.target.value;render();}else if(event.target.id==='reference-file')await uploadReference(event.target.files[0]);else if(event.target.id==='import-file'){await importFile(event.target.files[0]);event.target.value='';}else if(event.target.type==='radio'&&event.target.closest('#wizard-form')){captureWizard();await saveWizardDraft();render();}}catch(error){toast(error.message);}});
document.addEventListener('keydown',async event=>{if(event.target.matches('[role="tab"]')&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();let idx=tabs.findIndex(([k])=>k===state.tab);if(event.key==='Home')idx=0;else if(event.key==='End')idx=tabs.length-1;else idx=(idx+(event.key==='ArrowRight'?1:-1)*(getLanguage()==='ar'?-1:1)+tabs.length)%tabs.length;state.tab=tabs[idx][0];state.showArchived=false;if(state.tab==='story')await storyUI.load();render();$(`#tab-${state.tab}`).focus();}});
$('#editor').addEventListener('cancel',event=>{event.preventDefault();closeEditor().catch(e=>toast(e.message));});
window.addEventListener('pagehide',()=>{flushDraft();});
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;syncInstallControls();});
async function refresh(){const values=await Promise.all([store.getProjects(state.db),store.getSetting('language',state.db),store.getSetting('theme',state.db),store.getSetting('lastProject',state.db),store.getDraft('wizard',state.db)]);state.projects=values[0];setLanguage(values[1]||'en');state.theme=values[2]||'dark';state.lastProject=values[3];state.wizardDraft=values[4];}
async function init(){try{if(testMode)$('#app').dataset.testStartup='open-db';state.db=await store.openDB(testMode?'cinesaga-ai-ui-tests':store.DB_NAME);if(testMode)$('#app').dataset.testStartup='refresh';await refresh();if(testMode)$('#app').dataset.testStartup='seed';if(!await store.getSetting('demoSeeded',state.db)){if(!state.projects.some(p=>p.demo)){const p=model.createDemoSeries(getLanguage());await store.saveProject(p,state.db);state.projects.push(p);}await store.setSetting('demoSeeded',true,state.db);}if(testMode)$('#app').dataset.testStartup='render';render();if(testMode)window.CineSagaTest={setLanguage:async lang=>{setLanguage(lang);render();},getState:()=>({dbName:state.db.name,view:state.view,projects:structuredClone(state.projects)}),render,dispose:()=>state.db.close()};if('serviceWorker' in navigator&&!testMode){navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{state.offlineReady=true;const el=$('.offline-status');if(el)el.textContent='● '+t('offline');}).catch(()=>{const el=$('.offline-status');if(el)el.textContent=t('offlineUnavailable');});}}catch(error){$('#app').innerHTML=`<main class="main"><section class="panel"><h1>CineSaga AI</h1><p>${esc(error.message)}</p><p>Enable local browser storage and reload this page to open your studio.</p></section></main>`;}}
const mediaUI=createMediaUI({state,project,esc,button});
const consistencyUI=createConsistencyUI({state,project,esc,button,loadImages});
const identityUI=createIdentityUI({state,project,persist,render,esc,icon,tag,button,iconButton,toast,loadImages});
const storyUI=createStoryUI({state,project,render,esc,button,tag,toast});
init();
window.addEventListener('appinstalled',()=>{installPrompt=null;syncInstallControls();});
